\begin{aligned}
\hat{g}_1 &= \operatorname*{argmin}_{g}\left(\sum_{i=1}^{n}(y_i - g(x_i))^2 + \lambda \int \left[g^{(3)}(x)\right]^2 dx\right), \\
\hat{g}_2 &= \operatorname*{argmin}_{g}\left(\sum_{i=1}^{n}(y_i - g(x_i))^2 + \lambda \int \left[g^{(4)}(x)\right]^2 dx\right), \\
&\text{where } g^{(m)} \text{ represents the } m\text{th derivative of } g.
\end{aligned}
